content:
:root {
  --color-bg: #f8fafc;
  --color-surface: #ffffff;
  --color-surface-subtle: #f1f5f9;
  --color-border: #e2e8f0;
  --color-border-hover: #cbd5e1;
  --color-text-main: #0f172a;
  --color-text-muted: #64748b;
  --color-text-light: #94a3b8;

  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-soft: #eff6ff;
  --color-accent: #10b981;
  --color-warning: #f59e0b;
  --color-danger: #ef4444;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "BIZ UDPGothic", Meiryo, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリケーション全体レイアウト */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 32px 20px 60px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダー */
.app-header {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 20px;
}

.header-title {
  font-size: 1.85rem;
  font-weight: 700;
  color: var(--color-text-main);
  letter-spacing: -0.02em;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

/* KPIカードグリッド */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

@media (max-width: 960px) {
  .kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 520px) {
  .kpi-grid {
    grid-template-columns: 1fr;
  }
}

.kpi-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 12px;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.kpi-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.kpi-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text-main);
  line-height: 1.2;
  display: flex;
  align-items: baseline;
  gap: 4px;
  word-break: break-all;
}

.kpi-unit {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--color-text-muted);
}

.kpi-highlight {
  font-size: 0.78rem;
  font-weight: 500;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  background-color: var(--color-surface-subtle);
  color: var(--color-text-muted);
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* 操作バー */
.controls-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
}

.controls-group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.toggle-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-muted);
  background-color: var(--color-surface-subtle);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.toggle-btn:hover {
  background-color: var(--color-border-hover);
  color: var(--color-text-main);
}

.toggle-btn--active {
  background-color: var(--color-primary-soft);
  color: var(--color-primary);
  border-color: var(--color-primary);
  box-shadow: 0 0 0 1px var(--color-primary);
}

.action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--color-primary);
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
}

.action-btn:hover {
  background-color: var(--color-primary-hover);
}

.action-btn--secondary {
  color: var(--color-text-main);
  background-color: var(--color-surface);
  border-color: var(--color-border);
}

.action-btn--secondary:hover {
  background-color: var(--color-surface-subtle);
  border-color: var(--color-border-hover);
}

/* グラフカード */
.chart-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.chart-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.chart-card-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.chart-container {
  width: 100%;
  height: 380px;
  position: relative;
}

/* Rechartsカスタムツールチップ */
.chart-tooltip {
  background-color: rgba(15, 23, 42, 0.92);
  backdrop-filter: blur(4px);
  color: #ffffff;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-lg);
  font-size: 0.85rem;
  min-width: 160px;
}

.tooltip-month {
  font-weight: 700;
  margin-bottom: 8px;
  padding-bottom: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
}

.tooltip-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 4px;
}

.tooltip-label {
  color: #cbd5e1;
  display: flex;
  align-items: center;
  gap: 6px;
}

.tooltip-value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: #ffffff;
}

/* テーブルカード */
.table-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.table-card-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.table-card-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.table-card-desc {
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.table-container {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.sales-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.9rem;
}

.table-th {
  background-color: var(--color-surface-subtle);
  color: var(--color-text-muted);
  font-weight: 600;
  padding: 12px 14px;
  border-bottom: 1px solid var(--color-border);
  white-space: nowrap;
}

.table-td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--color-border);
  color: var(--color-text-main);
  font-variant-numeric: tabular-nums;
}

.sales-table tbody tr:hover {
  background-color: #fafbfc;
}

.table-input {
  width: 130px;
  padding: 6px 10px;
  font-size: 0.9rem;
  font-family: inherit;
  font-weight: 500;
  color: var(--color-text-main);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  text-align: right;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.table-input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

/* ユーティリティ */
.text-right {
  text-align: right;
}

.text-center {
  text-align: center;
}

export interface MonthlySalesItem {
  month: string;
  sales: number;
  target: number;
  prevYearSales: number;
}

export interface SummaryStats {
  totalSales: number;
  avgSales: number;
  maxSales: MonthlySalesItem;
  minSales: MonthlySalesItem;
}

export interface ChartDisplayOptions {
  showTarget: boolean;
  showPrevYear: boolean;
}

import { useMemo } from 'react';
import { MonthlySalesItem } from '../types';

interface SalesSummaryCardsProps {
  data?: MonthlySalesItem[];
}

const SalesSummaryCards = ({ data = [] }: SalesSummaryCardsProps) => {
  const stats = useMemo(() => {
    if (data.length === 0) {
      return {
        totalSales: 0,
        avgSales: 0,
        maxSales: { month: '-', sales: 0, target: 0, prevYearSales: 0 },
        minSales: { month: '-', sales: 0, target: 0, prevYearSales: 0 },
      };
    }

    let total = 0;
    let maxItem = data[0];
    let minItem = data[0];

    data.forEach((item) => {
      total += item.sales;
      if (item.sales > maxItem.sales) {
        maxItem = item;
      }
      if (item.sales < minItem.sales) {
        minItem = item;
      }
    });

    return {
      totalSales: total,
      avgSales: Math.round(total / data.length),
      maxSales: maxItem,
      minSales: minItem,
    };
  }, [data]);

  const formatCurrency = (val: number) => {
    return val.toLocaleString('ja-JP');
  };

  return (
    <div className="kpi-grid">
      <div className="kpi-card">
        <div className="kpi-label">年間合計売上</div>
        <div className="kpi-value">
          {formatCurrency(stats.totalSales)}
          <span className="kpi-unit">万円</span>
        </div>
        <div className="kpi-highlight">12ヶ月累計実績</div>
      </div>

      <div className="kpi-card">
        <div className="kpi-label">月間平均売上</div>
        <div className="kpi-value">
          {formatCurrency(stats.avgSales)}
          <span className="kpi-unit">万円</span>
        </div>
        <div className="kpi-highlight">月平均ペース</div>
      </div>

      <div className="kpi-card">
        <div className="kpi-label">最高売上月</div>
        <div className="kpi-value">
          {formatCurrency(stats.maxSales.sales)}
          <span className="kpi-unit">万円</span>
        </div>
        <div className="kpi-highlight">{stats.maxSales.month} 達成</div>
      </div>

      <div className="kpi-card">
        <div className="kpi-label">最低売上月</div>
        <div className="kpi-value">
          {formatCurrency(stats.minSales.sales)}
          <span className="kpi-unit">万円</span>
        </div>
        <div className="kpi-highlight">{stats.minSales.month} 記録</div>
      </div>
    </div>
  );
};

export default SalesSummaryCards;
